    (
        3,
        15,
        "",
        "Ehud the son of Gera, the Benjamite, a left-handed man",
        "comm",
        "Note",
        "Note",
        "<strong>The left-handed Benjaminite.</strong> The Hebrew is sharper than the English: <em>itter yad-y’mino</em>, literally “restricted in his right hand.” The detail matters narratively (Ehud could conceal a sword on his right thigh, where guards wouldn’t check) and ironically (<em>Benjamin</em> means “son of the right hand” — and yet his most famous warriors are the 700 left-handed slingers of 20:16). The Ehud-Eglon assassination (3:15–30) is one of the most darkly comic passages in scripture, full of scatological humor easily lost in translation — Eglon is a fat king, his servants delay entering because they assume he’s relieving himself.",
        "User original",
    ),
