        "<strong>Dictionary (Easton's).</strong> <strong>ANATH</strong> an answer; i.e., to “prayer”, the father of Shamgar, who was one of the judges of Israel (Judges 3:31). <em>[Reviewer: condense Easton's entry as needed.]</em>",
