    (
        4,
        4,
        "",
        "Now Deborah, a prophetess",
        "comm",
        "Note",
        "Note",
        "<strong>Deborah.</strong> The only judge in the book who is also a prophet, and the only female judge. The text introduces her without defensiveness or apology — her authority is simply stated. She holds court under a palm tree (4:5) and delivers oracles. The next chapter (the Song of Deborah, ch 5) is widely regarded as one of the oldest preserved pieces of Hebrew poetry — its archaic morphology probably places it in the 12th century BCE, making it potentially older than the prose narrative that frames it.",
        "User original",
    ),
