    (
        9,
        8,
        "",
        "to anoint a  king",
        "comm",
        "Note",
        "Note",
        "<strong>Jotham’s parable.</strong> The Bible’s first political fable. Olive, fig, and vine — productive trees — refuse the kingship; only the bramble accepts. The fable is one of the earliest and most pointed critiques of monarchy in scripture, predating the explicit anti-monarchic passages in 1 Sam 8 and 12. The fable turns on a productivity argument: those who do real work won’t leave it for empty status; only those with nothing to offer seek the throne.",
        "User original",
    ),
