    (
        13,
        5,
        "",
        "a  Nazirite to God from the womb",
        "comm",
        "Note",
        "Note",
        "<strong>Samson the lifelong Nazirite.</strong> Unlike the temporary Nazirite vow of Numbers 6, Samson is set apart from before birth. The contrast with the Nazirite ideal is, however, comic: he eats from a lion carcass (14:8–9, violating corpse-contact), drinks at a feast (14:10, “mishteh” — drinking-party — implying wine), and ends up in the lap of Delilah. The narrative deploys the Nazirite frame ironically — Samson is the most flawed of the judges, and yet, paradoxically, the deliverer.",
        "User original",
    ),
