    (
        19,
        29,
        "",
        "cut up his concubine, and divided her",
        "comm",
        "Note",
        "Note",
        "<strong>The Levite’s concubine.</strong> One of the darkest narratives in the Hebrew Bible. The Gibeah outrage (chs 19–21) consciously echoes the Sodom story (Gen 19) — but where Sodom’s strangers are angels who deliver Lot, here the concubine is delivered up by her own husband and dies on the threshold. The dismembered body sent to the twelve tribes is a grotesque parody of the covenant-cutting ritual (where animal pieces, not human, signaled binding agreement). The story’s placement at the end of the book is its commentary on the book: the cycle of judges has produced this. Phyllis Trible’s influential reading in <em>Texts of Terror</em> (1984) refuses to redeem the narrative — its purpose, she argues, is to be unbearable.",
        "User original",
    ),
